/**
 * The portal's copy, in both languages: every word the seller and admin portal
 * draws and the shop never does.
 *
 * **Its own module, so a shopper never downloads it.** The dictionary was one
 * module for both, and the portal's words were two fifths of it — about 80 KB
 * of every shopper's first download (gzipped), on a phone, for pages they will
 * never open. These are the keys used only by `pages/admin` and
 * `components/admin`; the portal's frame (`AdminShell`) imports this file,
 * which adds them to `translate` before any portal page is drawn, and the
 * server, the tests and the iOS export import it beside the dictionary.
 * `portalMessages.test.ts` keeps the line where it is: a key used anywhere the
 * shop draws belongs in `dictionary.ts`, and one used only by the portal here.
 *
 * Arabic is the dictionary's Modern Standard, and the same rules hold: `portalAr`
 * is typed as a complete record of the English keys.
 */
import { addMessages } from "./dictionary.js";

